mapper.select:
select ord.ORDER_ID as orderId, ord.BUSI_TYPE as busiType, ord.ORDER_TYPE as orderType, ord.ORDER_Num as orderNum, ord.SETTLE_DATE as settleDate, ord.TRADE_ID as tradeId, ord.MY_ACCT_NO as myAcctNo, ord.PS as ps, ord.COUNTER_ACCT_NO as counterAcctNo, ord.SETTLE_AMT as settleAmt, ord.SETTLE_STATUS as settleStatus, ba.BOOKSET_ID as booksetId, ba.BOOKSET_DATE as booksetDate, ba.BOOK_DATE as bookDate from stl_ORDERS ord left join bok_DEAL_ACCOUNTING ba on ba.BUSI_TABLE = #{busiTable} and ba.BUSI_NO = ord.ORDER_ID where 1=1
and ord.TRADE_ID LIKE '%'||#{tradeId}||'%'
and ord.BUSI_TYPE = #{busiType}
and ord.PS = #{ps}
and ord.SETTLE_DATE >= #{settleDateStart,jdbcType=DATE}
and ord.SETTLE_DATE <= #{settleDateEnd,jdbcType=DATE}
